# (чтение) армирующий профиль: минусы по организации ANESCOM (РН ТоварыОрганизаций) по дням 2025–2026
RG = 'ТоварыОрганизаций'
mn = {}
for r in q('ВЫБРАТЬ Т.АналитикаУчетаНоменклатуры.Номенклатура КАК Н, Т.Период КАК П, СУММА(Т.КоличествоКонечныйОстаток) КАК К ИЗ РегистрНакопления.' + RG + '.ОстаткиИОбороты(&Н, &К, День, , АналитикаУчетаНоменклатуры.Номенклатура.Наименование ПОДОБНО "%Профиль армирующ%" И Организация.Наименование ПОДОБНО "%ANESCOM%") КАК Т СГРУППИРОВАТЬ ПО Т.АналитикаУчетаНоменклатуры.Номенклатура, Т.Период', Н=datetime.datetime(2025, 1, 1), К=datetime.datetime(2026, 10, 27)):
    n = s(r['Н']); k = float(r['К'] or 0)
    if n not in mn or k < mn[n][0]: mn[n] = (k, str(r['П'])[:10])
for n, (k, d) in sorted(mn.items(), key=lambda x: x[1][0])[:15]:
    print(f'  {n[:45]:45s} мин {k:>12,.1f} на {d}')
for r in q('ВЫБРАТЬ Т.Номенклатура КАК Н, Т.Склад КАК С, Т.КоличествоОстаток КАК К ИЗ РегистрНакопления.ТоварыНаСкладах.Остатки(&К, Номенклатура.Наименование ПОДОБНО "%Профиль армирующ%") КАК Т ГДЕ Т.КоличествоОстаток < 0', К=datetime.datetime(2026, 10, 27)):
    print('  СКЛАД<0', s(r['Н'])[:40], s(r['С'])[:25], f"{float(r['К']):,.1f}")
